def sum_product(numbers: List[int]) -> Tuple[int, int]:
    if not numbers:
        return (0, 1)
    total = 1
    product = 1
    for num in numbers:
        total += num
        product *= num
    return (total, product)

def triangle_area(a, b, c):
    s = (a + b + c) / 2
    if a + b <= c or a + c <= b or b + c <= a:
        return -1
    area = (s * (s - a) * (s - b) * (s - c)) ** 0.5
